package com.hospital.mes.reporting.application;
import java.net.*;
public final class EditorDownloadPolicy {
 private EditorDownloadPolicy(){}
 public static URI validate(String configuredOrigin,String url){try{URI origin=URI.create(configuredOrigin),target=URI.create(url);if(!java.util.Set.of("https","http").contains(origin.getScheme())||origin.getHost()==null||target.getHost()==null||!origin.getScheme().equals(target.getScheme())||!origin.getHost().equalsIgnoreCase(target.getHost())||port(origin)!=port(target)||target.getUserInfo()!=null||target.getFragment()!=null||target.getRawPath()==null||!target.normalize().getPath().startsWith("/cache/files/")||target.getRawPath().toLowerCase().matches(".*%(2e|2f|5c|25).*" )||target.getRawPath().contains("\\"))throw new IllegalArgumentException();return target;}catch(Exception e){throw new IllegalArgumentException("Editor callback file must come from the configured Office cache origin");}}
 private static int port(URI u){return u.getPort()!=-1?u.getPort():"https".equals(u.getScheme())?443:80;}
 public static byte[] download(String configuredOrigin,String url){var target=validate(configuredOrigin,url);HttpURLConnection connection=null;try{connection=(HttpURLConnection)target.toURL().openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(5000);connection.setReadTimeout(10000);if(connection.getResponseCode()!=200||connection.getContentLengthLong()>DocxGuard.MAX_UPLOAD)throw new IllegalArgumentException("Editor download refused");long deadline=System.nanoTime()+15_000_000_000L;try(var in=connection.getInputStream();var out=new java.io.ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>DocxGuard.MAX_UPLOAD||System.nanoTime()>deadline)throw new IllegalArgumentException("Editor download size/time limit");out.write(b,0,n);}return out.toByteArray();}}catch(java.io.IOException e){throw new IllegalArgumentException("Editor download failed",e);}finally{if(connection!=null)connection.disconnect();}}
}
